from pathlib import Path
import json,hashlib,html,collections
P=Path(__file__).resolve().parent
panels=json.loads((P/'ANNOTATIONS.json').read_text())
rows=[r for p in panels for r in p['rows']]
source={'url':'https://www.skyscript.co.uk/pdf/pubs/texts/albiruni/docs/albiruni.pdf','work_date':'1029 as stated on edition title page','edition':'R. Ramsay Wright, London: Luzac,1934','file':'albiruni-wright.pdf','scope':'128-page English astrology extract, not the complete bilingual volume','verified_pages':{'title_pdf_page':3,'male_female':{'section':457,'pdf_page':63,'scan_page':62},'brightness':{'section':458,'pdf_page':64,'scan_page':63}},'sequence_status':'Page images inspected after inventory freeze. No machine-readable degree sequences admitted or scores computed. Table has five brightness categories; glyph/code ambiguity must be resolved during separate transcription review.','categories':['brilliant','luminous','dusky','dark or shadowed','empty or void'],'misleading_lead':'isamveri DKM092165.pdf is a bibliographic dossier, not the full book. Prior spoken description corrected. Preserved as isam-bibliographic-dossier.pdf.'}
(P/'PRIMARY-SOURCE.json').write_text(json.dumps(source,indent=2),encoding='utf-8')
status={'mapping':'First-pass location inventory complete across eight development panels; not an independently validated segmentation','locations':len(rows),'uncertain_presence':sum('presence' in r for r in rows),'candidate_label_anchors':sum(r['label_anchor'] is not None for r in rows),'unresolved_label_anchors':sum(r['label_anchor'] is None for r in rows),'body_ambiguous':sum(r['body'] is None for r in rows),'enclosure_ambiguous':sum(r['enclosure'] is None for r in rows),'star_pigmentation':'Not estimable in this pass: all fields unresolved; not evidence of unpainted stars','primary_scan':'obtained and relevant table page images verified','heldout_annotated':False,'heldout_scored':False,'alignment_scored':False,'not_completed':['Precise label bounding polygons and unique label-to-figure ownership','Reliable pigment classifications','Independent annotation audit','Degree-table transcription and scoring qualification'],'geometry_freeze':'GEOMETRY-FREEZE.json','inventory_pre_table_freeze':'INVENTORY-FIRST-PASS-FREEZE.json'}
(P/'STATUS.json').write_text(json.dumps(status,indent=2),encoding='utf-8')
esc=lambda x:html.escape(str(x))
cards=''
for p in panels:
 local=p.get('local_image',p['folio']+'.jpg')
 x0,y0,w,h=p['region']
 svg=f'<svg viewBox="0 0 {w} {h}" role="img" aria-label="Annotated {p["folio"]}"><image href="{local}" width="{w}" height="{h}"/>'
 for r in p['rows']:
  x,y=r['head']; x-=x0;y-=y0
  colour='#ff557d' if 'presence' in r else '#1547d2'
  title=esc(r['id']+' | '+(r['body'] or 'torso ambiguous')+' | '+(r['enclosure'] or 'enclosure ambiguous')+' | '+r['label_association'])
  svg+=f'<g class="heads"><title>{title}</title><circle cx="{x}" cy="{y}" r="17" fill="white" stroke="{colour}" stroke-width="5"/><text x="{x+21}" y="{y}" font-size="32" fill="{colour}" stroke="white" stroke-width=".6">{r["group"][0]}{r["index"]}</text></g>'
  if r['label_anchor']:
   lx,ly=r['label_anchor'];lx-=x0;ly-=y0
   svg+=f'<g class="labels"><title>{title}: candidate label point, not confirmed ownership</title><line x1="{x}" y1="{y}" x2="{lx}" y2="{ly}" stroke="#b34800" stroke-width="3" stroke-dasharray="8 8"/><rect x="{lx-10}" y="{ly-10}" width="20" height="20" fill="#e46b00" stroke="white" stroke-width="3"/></g>'
 svg+='</svg>'
 counts=collections.Counter(r['group'] for r in p['rows'])
 table=''.join('<tr><td>'+esc(r['id'])+'</td><td>'+esc(r['body'] or 'ambiguous')+'</td><td>'+esc(r['enclosure'] or 'ambiguous')+'</td><td>'+esc(r.get('presence',r['ambiguity']) or 'No additional note')+'</td></tr>' for r in p['rows'])
 cards+=f'<section><h2>{p["folio"]} · {p["sign"]}</h2><p>{esc(dict(counts))}</p><p>{esc(p["note"])}</p><div class="map">{svg}</div><p><a href="{local}">Unmarked image</a></p><details><summary>Feature records and exceptions</summary><table><tr><th>ID</th><th>Torso</th><th>Enclosure</th><th>Exception</th></tr>{table}</table></details></section>'
doc='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Zodiac mapping v84</title><style>body{background:#101c25;color:#edf3f4;font:17px/1.6 system-ui;max-width:1150px;margin:40px auto;padding:0 22px}h1{font-size:38px}a{color:#8fe1ce}.banner{background:#243943;padding:22px;border-left:5px solid #8fe1ce}section{margin:35px 0;padding:22px;background:#1b2a34;border-radius:12px}.map{max-width:900px;margin:auto}svg{width:100%;height:auto}table{width:100%;border-collapse:collapse;font-size:14px}td,th{padding:8px;text-align:left;border-bottom:1px solid #48606c}.controls{position:sticky;top:0;background:#233b49;padding:12px;z-index:1}button{font:inherit;margin:5px;padding:6px 15px}summary{cursor:pointer}.hidden-labels .labels{display:none}.hidden-heads .heads{display:none}</style><h1>Zodiac mapping · v84</h1><p class="banner"><b>Eight development panels mapped in a first visual pass. No alignment scores.</b> 179 recorded locations include one uncertain-presence location at Leo's fold. 177 candidate adjacent-label points; two unresolved. These are approximate locators, not precise segmentation or proven label ownership.</p><p>Geometry rules were frozen first. The complete first-pass inventory was saved and hashed before viewing the historical degree-table pages. No glyph readings or translations were used.</p><h2>What is—and isn't—finished</h2><p>The figure inventory, approximate label locations and torso/enclosure judgments are recorded. All star-pigment fields remain unresolved: pale outlines cannot safely be treated as unpainted stars. Unique label ownership, precise label polygons and an independent annotation audit are not established. Nulls and the possible Leo figure are kept in the data.</p><p>Held out: <b>Virgo, Libra, Scorpio, Sagittarius</b>. None individually annotated or scored. Prior v83 exposure notes remain: catalogue descriptions and a narrow Virgo fringe were seen; this was not complete visual blinding.</p><h2>Frozen geometry changes</h2><ul><li>Keep Pisces's29 observed locations; no invented thirtieth figure or fitted missing degree.</li><li>Gemini's extra-top group remains separate; Cancer retains three uneven bands.</li><li>Common traversal alternatives must enter the search correction. No per-sign phase tuning.</li><li>Future tests must beat panel/ring baselines and ring-preserving cyclic shifts.</li><li>Leo's fold location is uncertain. It cannot silently supply the thirtieth degree.</li></ul><h2>Primary source recovered</h2><p><a href="https://www.skyscript.co.uk/pdf/pubs/texts/albiruni/docs/albiruni.pdf">Wright1934 English astrology extract of al-Biruni's work dated1029</a>: §457 at PDF page63; §458 at PDF page64. Both page images have been visually inspected. §458 distinguishes five brightness categories. No degree sequence has been fitted to these images.</p><p><a href="wright-pdf-63.png">Male/female table image</a> · <a href="wright-pdf-64.png">Brightness table image</a> · <a href="albiruni-wright.pdf">Saved source PDF</a></p><p>The alternate library download proved to be a bibliographic dossier, not the book. That failed lead and the original access failures are retained.</p><div class="controls"><button onclick="document.body.classList.toggle('hidden-heads')">Toggle figure points</button><button onclick="document.body.classList.toggle('hidden-labels')">Toggle label candidates</button><span>Blue circles: heads · orange squares: candidate labels · pink: uncertain figure</span></div>'''+cards+'''<h2>Receipts</h2><p><a href="GEOMETRY.json">Geometry rules</a> · <a href="GEOMETRY-FREEZE.json">Rule freeze</a> · <a href="ANNOTATIONS.json">All annotations</a> · <a href="INVENTORY-FIRST-PASS-FREEZE.json">Pre-table inventory freeze</a> · <a href="STATUS.json">Status and limits</a> · <a href="PRIMARY-SOURCE.json">Source provenance</a></p></html>'''
(P/'report.html').write_text(doc,encoding='utf-8')
assert len(rows)==179 and len({r['id'] for r in rows})==179
for p in panels: assert (P/p.get('local_image',p['folio']+'.jpg')).exists()
(P/'SHA256SUMS.json').write_text(json.dumps({p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in P.iterdir() if p.is_file() and p.name!='SHA256SUMS.json'},indent=2),encoding='utf-8')
print(json.dumps(status,indent=2))
